#!/usr/bin/env python3
"""Validate restoration contracts against schemas generated by the selected Codex.

Requires Python jsonschema. Uses only an isolated temporary schema directory;
does not launch an authenticated agent or modify Codex configuration.
"""
import argparse
import json
from pathlib import Path
import re
import subprocess
import tempfile

from jsonschema import Draft7Validator

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--codex", default="codex")
parser.add_argument("--schema-dir", type=Path)
args = parser.parse_args()
root = Path(__file__).resolve().parent.parent
print(subprocess.check_output([args.codex, "--version"], text=True).strip())
schema_dir = args.schema_dir or Path(tempfile.mkdtemp(prefix="codex-monitor-contracts-"))
if args.schema_dir is None:
    subprocess.run([args.codex, "app-server", "generate-json-schema", "--experimental", "--out", str(schema_dir)], check=True)


def schema(name):
    return json.loads(next(schema_dir.rglob(name + ".json")).read_text())


client = schema("ClientRequest")
client_methods = {entry["properties"]["method"]["enum"][0] for entry in client["oneOf"]}
source = "\n".join(path.read_text() for path in (root / "src-tauri/src").rglob("*.rs"))
outgoing = set(re.findall(r'\.send_request(?:_for_workspace)?\(\s*(?:&?[^,\n]+,\s*)?"([a-zA-Z][\w/]+)"', source))
assert not outgoing - client_methods, f"Unknown outgoing methods: {outgoing - client_methods}"

fixtures = json.loads((root / "tests/fixtures/app-server-contracts.json").read_text())
for name, payloads in fixtures.items():
    validator = Draft7Validator(schema(name))
    for payload in payloads:
        validator.validate(payload)

# Guard the original failure: a command decision is not a permission grant.
assert list(Draft7Validator(schema("PermissionsRequestApprovalResponse")).iter_errors({"decision": "accept"}))
print(f"Validated {len(outgoing)} outgoing methods and {sum(map(len, fixtures.values()))} payload fixtures.")
print(f"Schema evidence: {schema_dir}")
